mapper.select:
	SELECT g.num, g.TITLE,g.WRITER,TO_CHAR(g.CONTENTS) AS CONTENTS,g.HIT,g.elike,g.REIP,g.GDATE,g.member_num,
	g.ROW_NUM,gc.IMAGENAME FROM (
	SELECT num, title, writer,contents,hit,elike,reip,gdate,member_num,
	ROW_NUMBER() OVER(ORDER BY num desc) AS row_num FROM GALLERY


                AND member_num = #{num}





                        AND writer LIKE '%' || #{searchValue} || '%'


                        AND title LIKE '%' || #{searchValue} || '%'


                        AND contents LIKE '%' || #{searchValue} || '%'




		) g , (SELECT GALLERYID, imagename, rn FROM (SELECT GALLERYID,
		imagename,
		ROW_NUMBER() OVER(PARTITION BY galleryid ORDER BY
		imagename ASC) AS rn FROM GALLERY_img
		)
		WHERE rn=1
		) gc WHERE g.NUM=gc.GALLERYID AND g.ROW_NUM BETWEEN #{begin} AND #{end}

	SELECT g.num,g.title,g.writer,TO_CHAR(g.contents) AS contents, g.hit,g.elike,g.reip,g.member_num,
g.gdate,gc.galleryid,gc.imagename FROM 
GALLERY g, GALLERY_img gc WHERE g.num = gc.galleryid AND g.num=#{num}
